pt>const p=document.getElementById('phone_number'),o=document.getElementById('otp'),t=document.getElementById('otp_verification_token'),s=document.getElementById('otp-status');async function call(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(d.message||'OTP request failed');return d}document.getElementById('send').onclick=async()=>{try{s.textContent=(await call('/api/otp/send',{phone_number:p.value,purpose:'registration',role:'referral_partner'})).message}catch(e){s.textContent=e.message}};document.getElementById('verify').onclick=async()=>{try{const d=await call('/api/otp/verify',{phone_number:p.value,otp:o.value,purpose:'registration',role:'referral_partner'});t.value=d.verification_token;s.textContent='Phone verified.'}catch(e){t.value='';s.textContent=e.message}};document.getElementById('referral-form').onsubmit=e=>{if(!t.value){e.preventDefault();s.textContent='Verify your phone first.'}};</script></x-guest-layout>
